from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._next_id = 1
        # appointment_id -> dict with patient, doctor, start, end, canceled, blocked
        self._appointments = {}

    def _overlaps(self, a_start, a_end, b_start, b_end):
        return a_start < b_end and b_start < a_end

    def _is_active(self, appt):
        # An appointment is active (blocks time) unless it was canceled and
        # the cancellation actually freed the slot.
        if not appt["canceled"]:
            return True
        # If canceled but slot stayed blocked, it still blocks.
        return appt["blocked"]

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment that starts in the past.")
        if end <= start:
            raise ValueError("Appointment end must be after start.")

        # Check patient's upcoming appointments.
        for appt in self._appointments.values():
            if appt["patient"] != patient:
                continue
            if appt["canceled"] and not appt["blocked"]:
                continue
            # Upcoming means it hasn't ended yet as of 'now'.
            if appt["end"] > now:
                raise ValueError(
                    f"Patient '{patient}' already has an upcoming appointment."
                )

        # Check doctor availability.
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not free during the requested time."
            )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "canceled": False,
            "blocked": False,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError(f"No appointment with id {appointment_id}.")
        appt = self._appointments[appointment_id]
        if appt["canceled"]:
            return
        appt["canceled"] = True
        # If canceled less than 24 hours before start, the slot stays blocked.
        if appt["start"] - now < timedelta(hours=24):
            appt["blocked"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not self._is_active(appt):
                continue
            if self._overlaps(start, end, appt["start"], appt["end"]):
                return False
        return True
